package practice;

import java.util.Arrays;
import java.util.List;
import java.util.function.Consumer;
import java.util.stream.Stream;

/** Tells the customers of a region that an outage is planned, by every channel they gave us. */
public class OutageNotifier {

    /** A customer from the CRM. Either contact may be missing (null). */
    public record Customer(String name, String email, String phone, int[] quietHours) {}

    /** Sends the notice to every contact of the segment, except during a customer's quiet hours. */
    public int notify(List<Customer> segment, int hour, Consumer<String> send) {
        int sent = 0;
        for (Customer c : segment == null ? List.<Customer>of() : segment) {
            if (isQuietHour(c.quietHours(), hour)) continue;
            for (String contact : contacts(List.of(c))) {
                send.accept(contact);
                sent++;
            }
        }
        return sent;
    }

    /**
     * The contacts of a segment: each customer's email, then phone, customer by customer, leaving
     * out missing ones. The CRM returns null for a segment with no customers.
     */
    List<String> contacts(List<Customer> segment) {
        return Stream.ofNullable(segment)
                .flatMap(List::stream)
                .flatMap(c -> Stream.concat(Stream.ofNullable(c.email()), Stream.ofNullable(c.phone())))
                .toList();
    }

    /** Whether hour (0-23) is one of the customer's quiet hours. */
    boolean isQuietHour(int[] quietHours, int hour) {
        return Arrays.stream(quietHours).anyMatch(h -> h == hour);
    }
}

package practice;

import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Level;
import java.util.logging.Logger;

/** Run executes this file. Change the calls in main and see what prints. Submit grades. */
public class TryIt {
    /** Held here, so the JDK's own exit notice stays off: a logger nothing holds can be dropped. */
    private static final Logger JDK_EXIT = Logger.getLogger("java.lang.Runtime");

    public static void main(String[] args) {
        // Turn the logger up, so the log lines of your code show under the printed lines.
        System.setProperty("java.util.logging.SimpleFormatter.format", "%4$s %5$s%n");
        // Only this handler prints, and it leaves out the JDK's own detail.
        Logger root = Logger.getLogger("");
        for (java.util.logging.Handler before : root.getHandlers()) {
            root.removeHandler(before);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFilter(entry -> !String.valueOf(entry.getLoggerName()).matches("(java|javax|jdk|sun|com\\.sun)\\..*"));
        root.setLevel(Level.ALL);
        root.addHandler(handler);
        JDK_EXIT.setLevel(Level.OFF);

        // A stand-in for the collaborator, like the one the tests use for the first main case.
        try {
            OutageNotifier notifier = new OutageNotifier();
            List<OutageNotifier.Customer> region = List.of(
                    new OutageNotifier.Customer("Ada Example", "ada@example.com", "+1-555-0150", new int[] {}),
                    new OutageNotifier.Customer("Ben Example", null, "+1-555-0151", new int[] {}),
                    new OutageNotifier.Customer("Cleo Example", "cleo@example.com", null, new int[] {0, 1, 2}));
            System.out.println("contacts: " + notifier.contacts(region));
            System.out.println("is 1 a quiet hour of {0, 1, 2}: " + notifier.isQuietHour(new int[] {0, 1, 2}, 1));
            int sent = notifier.notify(region, 1, contact -> System.out.println("sent to " + contact));
            System.out.println("sent at 01:00: " + sent);
            System.out.println("sent to an empty region: " + notifier.notify(null, 1, contact -> { }));
        } catch (RuntimeException stopped) {
            // A method you have not finished, or a bug, stops here with its message, not a build error.
            System.out.println("Run stopped: " + stopped);
        }
    }
}

